class Solution {
public:
    bool canWin(string currentState) {
        unordered_map<string, bool> memo;
        return dfs(currentState, memo);
    }

private:
    bool dfs(const string& s, unordered_map<string, bool>& memo) {
        if (memo.count(s)) return memo[s];
        int n = s.size();
        for (int i = 0; i < n - 1; ++i) {
            if (s[i] == '+' && s[i + 1] == '+') {
                string nextState = s;
                nextState[i] = '-';
                nextState[i + 1] = '-';
                if (!dfs(nextState, memo)) {
                    return memo[s] = true;
                }
            }
        }
        return memo[s] = false;
    }
};

class Solution {
    public boolean canWin(String currentState) {
        Map<String, Boolean> memo = new HashMap<>();
        return dfs(currentState, memo);
    }

    private boolean dfs(String s, Map<String, Boolean> memo) {
        if (memo.containsKey(s)) return memo.get(s);
        char[] arr = s.toCharArray();
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] == '+' && arr[i + 1] == '+') {
                arr[i] = '-';
                arr[i + 1] = '-';
                String nextState = new String(arr);
                boolean opponentWins = dfs(nextState, memo);
                arr[i] = '+';
                arr[i + 1] = '+';
                if (!opponentWins) {
                    memo.put(s, true);
                    return true;
                }
            }
        }
        memo.put(s, false);
        return false;
    }
}

