var canWin = function(currentState) {
    const memo = new Map();
    function dfs(s) {
        if (memo.has(s)) return memo.get(s);
        for (let i = 0; i < s.length - 1; i++) {
            if (s[i] === '+' && s[i + 1] === '+') {
                const nextState = s.slice(0, i) + "--" + s.slice(i + 2);
                if (!dfs(nextState)) {
                    memo.set(s, true);
                    return true;
                }
            }
        }
        memo.set(s, false);
        return false;
    }
    return dfs(currentState);
};
